LEVELS = {'low': 1, 'moderate': 2, 'high': 3}
NAMES = {v: k for k, v in LEVELS.items()}

assets = [
    {'name': 'Marketing website', 'owner': 'Marketing Head', 'c': 'low', 'i': 'moderate', 'a': 'moderate'},
    {'name': 'Payroll database', 'owner': 'HR Director', 'c': 'high', 'i': 'high', 'a': 'moderate'},
    {'name': 'Build server', 'owner': '', 'c': 'moderate', 'i': 'high', 'a': 'low'},
]

for asset in assets:
    level = max(LEVELS[asset[k]] for k in ('c', 'i', 'a'))  # high-water mark
    asset['category'] = NAMES[level]
    if not asset['owner']:
        print(f"WARNING: {asset['name']} has no data owner; nobody is accountable")

for asset in sorted(assets, key=lambda a: -LEVELS[a['category']]):
    print(f"{asset['category']:>8}  {asset['name']}  (C={asset['c']}, I={asset['i']}, A={asset['a']})")
